// === routes/menu.js ===
import { Router } from 'express';
const menu = [{ id: 1, nama: 'Kopi Susu', harga: 18000 }];
let nextId = 2;
const router = Router();
function cari(req, res) {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) res.status(404).json({ error: 'Menu tidak ada' });
  return m;
}
router.get('/', (req, res) => {
  const q = String(req.query.q ?? '').toLowerCase();
  res.json(menu.filter((m) => m.nama.toLowerCase().includes(q)));
});
router.get('/:id', (req, res) => {
  const m = cari(req, res);
  if (m) res.json(m);
});
router.post('/', (req, res) => {
  const { nama, harga } = req.body;
  if (typeof nama !== 'string' || !(harga > 0)) return res.status(400).json({ error: 'nama dan harga wajib' });
  const baru = { id: nextId++, nama, harga };
  menu.push(baru);
  res.status(201).location(`${req.baseUrl}/${baru.id}`).json(baru);
});
router.patch('/:id', (req, res) => {
  const m = cari(req, res);
  if (!m) return;
  if (req.body.nama !== undefined) m.nama = req.body.nama;
  if (req.body.harga !== undefined) m.harga = req.body.harga;
  res.json(m);
});
router.delete('/:id', (req, res) => {
  const m = cari(req, res);
  if (!m) return;
  menu.splice(menu.indexOf(m), 1);
  res.sendStatus(204);
});
export default router;
// === main.js ===
import express from 'express';
import menuRouter from './routes/menu.js';
const app = express();
app.use(express.json());
app.use('/api/menu', menuRouter);
const server = app.listen(3000);

const u = 'http://localhost:3000/api/menu';
const kirim = (method, jalur, body) => fetch(u + jalur, { method, headers: { 'Content-Type': 'application/json' }, body: body && JSON.stringify(body) });
let r = await kirim('POST', '', { nama: 'Es Kopi', harga: 15000 });
console.log(r.status, r.headers.get('location'));
r = await kirim('PATCH', '/1', { harga: 20000 });
console.log(r.status, (await r.json()).harga);
r = await kirim('DELETE', '/9');
console.log(r.status);
r = await kirim('GET', '?q=kopi');
console.log((await r.json()).map((m) => `${m.nama} ${m.harga}`));
server.close();

