import express from 'express';
const menu = [{ id: 1, nama: 'Kopi', harga: 18000 }];
const router = express.Router();
router.patch('/:id', (req, res) => {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) return res.status(404).json({ error: 'Menu tidak ada' });
  if (req.body.harga !== undefined) m.harga = req.body.harga;
  res.json(m);
});
const app = express();
app.use(express.json());
app.use('/api/menu', router);
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/api/menu/1', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ harga: 25000, id: 99 }) });
